CREATE SET TABLE MDP01_META.META_ETL_RUN ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      run_id INTEGER NOT NULL,      etl_job_id INTEGER NOT NULL,      run_timestamp TIMESTAMP(6) NOT NULL,      status VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      exit_code INTEGER,      start_time TIMESTAMP(6) NOT NULL,      end_time TIMESTAMP(6),      duration_seconds DECIMAL(18,3),      rows_read DECIMAL(18,0),      rows_inserted DECIMAL(18,0),      rows_updated DECIMAL(18,0),      rows_deleted DECIMAL(18,0),      rows_rejected DECIMAL(18,0),      error_message VARCHAR(4000) CHARACTER SET LATIN NOT CASESPECIFIC,      error_stack CLOB(16777216) CHARACTER SET UNICODE,      execution_user VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      execution_host VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      execution_mode VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      parent_run_id INTEGER,      retry_attempt INTEGER DEFAULT 0 ,      ersterfassungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( run_id )INDEX ( etl_job_id ,run_timestamp );